38	/// Exponential delay: base * 2^(attempt - 1), saturating at Duration::MAX.
39	pub(crate) fn exp_delay(base: Duration, attempt: u32) -> Duration {
40	    let shift = attempt.saturating_sub(1).min(16);
41	    base.checked_mul(1u32 << shift).unwrap_or(Duration::MAX)
42	}
43	
44	/// Spreads retries of concurrent clients so they do not fire in lockstep.
45	pub(crate) fn with_jitter(delay: Duration) -> Duration {
46	    delay.mul_f64(1.0 + jitter_fraction())
47	}
48	
49	// Jitter is uniform in [-JITTER, +JITTER]: up to half of the delay either way.
50	const JITTER: f64 = 0.5;
51	
52	fn jitter_fraction() -> f64 {
53	    let r: f64 = rand::random();
54	    (r * 2.0 - 1.0) * JITTER
55	}
56	
57	/// Full jitter: a uniform delay between zero and `delay`.
58	pub(crate) fn full_jitter(delay: Duration) -> Duration {
59	    let r: f64 = rand::random();
60	    delay.mul_f64(r)
61	}
62	
63	/// Decorrelated jitter: the next delay depends on the previous one, bounded by `cap`.
64	pub(crate) fn decorrelated(previous: Duration, base: Duration, cap: Duration) -> Duration {
65	    let upper = previous.saturating_mul(3).max(base);
66	    let r: f64 = rand::random();
67	    (base + (upper - base).mul_f64(r)).min(cap)
68	}
69	
70	/// The delays of attempts 1, 2, 3, ... without jitter, each capped at `cap`.
71	pub(crate) struct Delays {
72	    base: Duration,
73	    cap: Duration,
74	    attempt: u32,
75	}
76	
77	impl Delays {
78	    /// Delays starting at `base`, capped at `cap`.
79	    pub(crate) fn new(base: Duration, cap: Duration) -> Self {
80	        Self { base, cap, attempt: 0 }
81	    }
82	}
83	
84	impl Iterator for Delays {
85	    type Item = Duration;
86	    fn next(&mut self) -> Option<Duration> {
87	        self.attempt = self.attempt.checked_add(1)?;
88	        Some(exp_delay(self.base, self.attempt).min(self.cap))
89	    }
90	}
91	
92	/// Total time spent waiting over `attempts` attempts, without jitter.
93	pub(crate) fn total_wait(base: Duration, cap: Duration, attempts: u32) -> Duration {
94	    Delays::new(base, cap).take(attempts.saturating_sub(1) as usize).sum()
95	}

